{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "The highest-transfer analogue, a tryptophan-derived hydroxamate, showed low brain uptake (0.84 %ID/g) in mice; the query shares the indole and hydroxamate warhead, supporting poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "An indole cinnamamide radiotracer showed very low brain uptake in rats (0.11–0.19 %ID/g across brain regions); the query's indole/cinnamoyl scaffold is closely analogous.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "JYL1421 was peripherally restricted with a brain/plasma ratio of 0.05–0.07 in rats, demonstrating that high-transfer analogues with polar/ionizable features do not achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "FLZ, a cinnamoyl-containing molecule, had a brain penetration ratio below 0.1 and was limited by P-gp efflux; the query's cinnamoyl/amine structure may be similarly effluxed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A positively charged amidine analogue had a brain:plasma ratio of 0.029 in mice; the query's secondary amine will be largely charged at physiological pH, predicting similarly poor penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show poor brain penetration or BBB impermeability, and the query shares key structural liabilities (indole, hydroxamate, ionizable amine), so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux transporter status of the query is not directly measured; inferred from analogue C04.",
    "Hydroxamate ionization and plasma protein binding are not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

